<?php
// Included by index.php after authentication and CSRF initialization.
if(!isset($db)){http_response_code(404);exit;}
function agentSetup(){global $db;$db->exec("CREATE TABLE IF NOT EXISTS onb_agents(user_id INT PRIMARY KEY,active TINYINT NOT NULL DEFAULT 1,code VARCHAR(32) NOT NULL UNIQUE)");$db->exec("CREATE TABLE IF NOT EXISTS onb_agent_leads(id INT AUTO_INCREMENT PRIMARY KEY,agent_id INT NOT NULL,trip_id INT NULL,name VARCHAR(150) NOT NULL,email VARCHAR(254) NOT NULL,stage VARCHAR(20) NOT NULL DEFAULT 'new',notes TEXT NOT NULL,followup DATE NULL,commission DECIMAL(12,2) NOT NULL DEFAULT 0,payout VARCHAR(20) NOT NULL DEFAULT 'pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(agent_id))");}
function agentActive($id){try{return (bool)q('SELECT active FROM onb_agents WHERE user_id=?',[$id])->fetchColumn();}catch(PDOException $e){return false;}}
function agentAction($action,$u,$admin){if(!$u||(!$admin&&!agentActive($u['id'])))throw new RuntimeException('Access denied.');
if($admin){agentSetup();agentExtrasSetup();}
if($action==='agent_rate'&&$admin){$rate=filter_var(p('rate'),FILTER_VALIDATE_FLOAT);$id=(int)p('id');if($rate===false||$rate<0||$rate>100000||!q('SELECT user_id FROM onb_agents WHERE user_id=?',[$id])->fetchColumn())throw new RuntimeException('Invalid rate');q('INSERT INTO onb_agent_rates(agent_id,rate) VALUES(?,?) ON DUPLICATE KEY UPDATE rate=VALUES(rate)',[$id,$rate]);}
elseif($action==='agent_enable'&&$admin){$id=q("SELECT id FROM users WHERE email=? AND role='traveller'",[strtolower(p('email'))])->fetchColumn();if(!$id)throw new RuntimeException('Account must register first.');q('INSERT INTO onb_agents(user_id,code) VALUES(?,?) ON DUPLICATE KEY UPDATE active=1',[$id,bin2hex(random_bytes(8))]);}
elseif($action==='agent_toggle'&&$admin){q('UPDATE onb_agents SET active=? WHERE user_id=?',[(int)(p('active')==='1'),(int)p('id')]);}
elseif($action==='agent_lead'&&!$admin){$trip=(int)p('trip_id');if($trip&&!q('SELECT id FROM trips WHERE id=? AND published=1',[$trip])->fetchColumn())throw new RuntimeException('Journey unavailable.');if(!filter_var(p('email'),FILTER_VALIDATE_EMAIL)||!p('name')||p('consent')!=='yes')throw new RuntimeException('Name, email and permission to contact are required.');q('INSERT INTO onb_agent_leads(agent_id,trip_id,name,email,notes) VALUES(?,?,?,?,?)',[$u['id'],$trip?:null,p('name'),p('email'),p('notes')]);}
elseif($action==='agent_update'){ $stage=p('stage');if(!in_array($stage,['new','contacted','qualified','won','lost'],true))throw new RuntimeException('Invalid stage.');$date=p('followup');if($date!==''&&(!preg_match('/^\d{4}-\d{2}-\d{2}$/D',$date)||!checkdate((int)substr($date,5,2),(int)substr($date,8,2),(int)substr($date,0,4))))throw new RuntimeException('Invalid date.');if($admin){$pay=p('payout');if(!in_array($pay,['pending','approved','paid'],true)||!is_numeric(p('commission'))||(float)p('commission')<0)throw new RuntimeException('Invalid commission.');$old=q('SELECT * FROM onb_agent_leads WHERE id=?',[(int)p('id')])->fetch();if(!$old||$old['payout']==='paid')throw new RuntimeException('Paid records are locked.');if($pay!=='pending'&&$stage!=='won')throw new RuntimeException('Only won leads qualify.');$commission=$stage==='won'?($old['payout']==='approved'?$old['commission']:(q('SELECT rate FROM onb_agent_rates WHERE agent_id=?',[$old['agent_id']])->fetchColumn()?:0)):0;if($pay==='paid'&&$old['payout']!=='approved')throw new RuntimeException('Approve first.');q('UPDATE onb_agent_leads SET stage=?,notes=?,followup=?,commission=?,payout=? WHERE id=?',[$stage,p('notes'),$date?:null,$commission,$pay,(int)p('id')]);}else{if($stage==='won')throw new RuntimeException('Administrator must verify wins.');q('UPDATE onb_agent_leads SET stage=?,notes=?,followup=? WHERE id=? AND agent_id=? AND payout=\'pending\'',[$stage,p('notes'),$date?:null,(int)p('id'),$u['id']]);}}
else throw new RuntimeException('Access denied.');go('page=agents');}
function agentView($u,$admin){if(!$u||(!$admin&&!agentActive($u['id']))){http_response_code(403);echo '<h2>Agent access required</h2>';return;}if($admin)agentSetup();$rows=q('SELECT l.*,t.title,u.name AS agent_name FROM onb_agent_leads l LEFT JOIN trips t ON t.id=l.trip_id JOIN users u ON u.id=l.agent_id'.($admin?'':' WHERE l.agent_id=?').' ORDER BY l.id DESC',$admin?[]:[$u['id']])->fetchAll(PDO::FETCH_ASSOC);?>
<div class="agent-space"><span class="eyebrow">OUR NEXT BOARDING / PARTNER NETWORK</span><h1><?=$admin?'Agent management':'Your sales workspace'?></h1><p>Manage relationships, follow-ups and commission records.</p><div class="metrics"><?php foreach(['Leads'=>count($rows),'Won'=>count(array_filter($rows,fn($r)=>$r['stage']==='won')),'Approved CAD'=>number_format(array_sum(array_column(array_filter($rows,fn($r)=>$r['payout']==='approved'),'commission')),2),'Paid CAD'=>number_format(array_sum(array_column(array_filter($rows,fn($r)=>$r['payout']==='paid'),'commission')),2)] as $k=>$v):?><article><span><?=h($k)?></span><strong><?=h($v)?></strong></article><?php endforeach;?></div>
<?php if($admin):?><h2>Enable an agent</h2><?php form('agent_enable');field('email','Registered account email','','email');?><button>Enable agent</button></form><?php foreach(q('SELECT a.*,u.name,u.email FROM onb_agents a JOIN users u ON u.id=a.user_id') as $a):?><article><strong><?=h($a['name'])?></strong> · <?=h($a['email'])?> · <?=$a['active']?'Active':'Disabled'?><?php form('agent_toggle');?><input type="hidden" name="id" value="<?=(int)$a['user_id']?>"><input type="hidden" name="active" value="<?=$a['active']?0:1?>"><button><?=$a['active']?'Disable':'Enable'?></button></form></article><?php endforeach;else:?><details><summary>Add customer lead</summary><?php form('agent_lead');field('name','Customer name');field('email','Customer email','','email');?><label>Journey<select name="trip_id"><option value="0">General enquiry</option><?php foreach(q('SELECT id,title FROM trips WHERE published=1') as $t):?><option value="<?=(int)$t['id']?>"><?=h($t['title'])?></option><?php endforeach;?></select></label><?php area('notes','Notes');?><label><input type="checkbox" name="consent" value="yes" required> Customer has agreed to be contacted</label><button>Add lead</button></form></details><p><a href="?page=trips">Browse and share published journeys</a></p><?php endif;?>
<?php agentExtrasView($u,$admin);?><h2>Customer pipeline</h2><?php if(!$rows):?><p>No leads yet.</p><?php endif;foreach($rows as $r):?><details><summary><?=h($r['name'])?> · <?=h($r['stage'])?> · <?=h($r['title']??'General enquiry')?></summary><p><?=h($r['email'])?> · <?=h($r['agent_name'])?></p><p>Commission CAD <?=h($r['commission'])?> · <?=h($r['payout'])?></p><?php form('agent_update');?><input type="hidden" name="id" value="<?=(int)$r['id']?>"><label>Stage<select name="stage"><?php foreach(['new','contacted','qualified','won','lost'] as $s):?><option <?=$r['stage']===$s?'selected':''?>><?=h($s)?></option><?php endforeach;?></select></label><label>Follow-up date<input type="date" name="followup" value="<?=h($r['followup'])?>"></label><?php area('notes','Notes',$r['notes']);if($admin):echo '<input type="hidden" name="commission" value="'.h($r['commission']).'"><p>Commission calculated from configured agent rate on verification.</p>';?><label>Payout<select name="payout"><?php foreach(['pending','approved','paid'] as $s):?><option <?=$r['payout']===$s?'selected':''?>><?=h($s)?></option><?php endforeach;?></select></label><?php endif;?><button>Save lead</button></form></details><?php endforeach;?></div><?php }

function agentExtrasSetup(){global $db;$db->exec("CREATE TABLE IF NOT EXISTS onb_agent_rates(agent_id INT PRIMARY KEY,rate DECIMAL(10,2) NOT NULL DEFAULT 0)");$db->exec("CREATE TABLE IF NOT EXISTS onb_agent_referrals(enquiry_id INT PRIMARY KEY,lead_id INT NOT NULL UNIQUE)");$db->exec("CREATE TABLE IF NOT EXISTS onb_agent_reminders(lead_id INT NOT NULL,due DATE NOT NULL,sent_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(lead_id,due))");}
function agentReferralCapture(){if(isset($_GET['ref'])&&is_string($_GET['ref'])&&preg_match('/^[a-f0-9]{16}$/D',$_GET['ref'])){try{$id=q('SELECT user_id FROM onb_agents WHERE code=? AND active=1',[$_GET['ref']])->fetchColumn();if($id)$_SESSION['agent_ref']=['id'=>(int)$id,'until'=>time()+2592000];}catch(PDOException $e){}}}
function agentAttribute($enquiry,$trip){$ref=$_SESSION['agent_ref']??[];if(($ref['until']??0)<time())return;$id=(int)$ref['id'];if(!agentActive($id))return;global $db;q('INSERT INTO onb_agent_leads(agent_id,trip_id,name,email,notes) VALUES(?,?,?,?,?)',[$id,$trip?:null,p('name'),p('email'),'Website referral enquiry #'.$enquiry]);$lead=$db->lastInsertId();q('INSERT INTO onb_agent_referrals(enquiry_id,lead_id) VALUES(?,?)',[$enquiry,$lead]);unset($_SESSION['agent_ref']);}
function agentStatement($u,$admin){if(!$u||(!$admin&&!agentActive($u['id']))){http_response_code(403);exit;} $id=$admin?(int)($_GET['agent_id']??0):(int)$u['id'];header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="commission-statement.csv"');header('Cache-Control: no-store');$f=fopen('php://output','w');fputcsv($f,['Lead ID','Journey','Created','Commission CAD','Payout']);foreach(q("SELECT l.id,t.title,l.created_at,l.commission,l.payout FROM onb_agent_leads l LEFT JOIN trips t ON t.id=l.trip_id WHERE l.agent_id=? AND l.stage='won' ORDER BY l.id",[$id]) as $r){$title=(string)$r['title'];if(preg_match('/^[\\s]*[=+@-]/',$title))$title="'".$title;fputcsv($f,[$r['id'],$title,$r['created_at'],$r['commission'],$r['payout']]);}fclose($f);exit;}
function agentExtrasView($u,$admin){agentExtrasSetup();?><section class="onb-dash"><h2>Partner performance</h2><?php if($admin):foreach(q('SELECT a.user_id,u.name,COALESCE(r.rate,0) rate FROM onb_agents a JOIN users u ON u.id=a.user_id LEFT JOIN onb_agent_rates r ON r.agent_id=a.user_id') as $a):form('agent_rate');?><input type="hidden" name="id" value="<?=(int)$a['user_id']?>"><label><?=h($a['name'])?> — fixed CAD per verified won lead<input type="number" min="0" max="100000" step=".01" name="rate" value="<?=h($a['rate'])?>" required></label><button>Save rate</button> <a href="?page=agent_statement&amp;agent_id=<?=(int)$a['user_id']?>">Download statement</a></form><?php endforeach;else:$code=q('SELECT code FROM onb_agents WHERE user_id=?',[$u['id']])->fetchColumn();?><label>Your referral link (copy and share)<input readonly value="<?=h('https://'.($_SERVER['HTTP_HOST']??'').$_SERVER['SCRIPT_NAME'].'?page=trips&ref='.$code)?>"></label><p><a href="?page=agent_statement">Download commission statement (CSV)</a></p><?php endif;?><h3>Follow-ups due</h3><?php foreach(q("SELECT l.id,l.name,l.followup FROM onb_agent_leads l WHERE l.followup<=CURRENT_DATE AND l.stage NOT IN ('won','lost')".($admin?'':' AND l.agent_id=?')." ORDER BY l.followup",$admin?[]:[$u['id']]) as $r):?><p><?=h($r['followup'].' · '.$r['name'])?></p><?php endforeach;?><h3>Leaderboard · verified wins</h3><div class="dash-table"><table><thead><tr><th>Rank</th><th>Partner</th><th>Wins</th></tr></thead><tbody><?php $rank=0;foreach(q("SELECT a.user_id,u.name,COUNT(l.id) wins FROM onb_agents a JOIN users u ON u.id=a.user_id LEFT JOIN onb_agent_leads l ON l.agent_id=a.user_id AND l.stage='won' AND l.payout IN ('approved','paid') WHERE a.active=1 GROUP BY a.user_id,u.name ORDER BY wins DESC,a.user_id") as $r):?><tr><td><?=++$rank?></td><td><?=h($admin?$r['name']:((int)$r['user_id']===(int)$u['id']?'You':'Partner '.$r['user_id']))?></td><td><?=h($r['wins'])?></td></tr><?php endforeach;?></tbody></table></div></section><?php }
